import{_ as e,c as a,o as l,aj as o}from"./chunks/framework.Dd-dAftz.js";const p=JSON.parse('{"title":"大模型应用开发 · 从零系统学习计划（前端 · 冲刺版）","description":"","frontmatter":{},"headers":[],"relativePath":"learning-plan/大模型应用开发/index.md","filePath":"learning-plan/大模型应用开发/index.md","lastUpdated":1783503504000}'),r={name:"learning-plan/大模型应用开发/index.md"};function i(d,t,n,s,c,h){return l(),a("div",null,[...t[0]||(t[0]=[o(`<h1 id="大模型应用开发-·-从零系统学习计划-前端-·-冲刺版" tabindex="-1">大模型应用开发 · 从零系统学习计划（前端 · 冲刺版） <a class="header-anchor" href="#大模型应用开发-·-从零系统学习计划-前端-·-冲刺版" aria-label="Permalink to &quot;大模型应用开发 · 从零系统学习计划（前端 · 冲刺版）&quot;">​</a></h1><blockquote><p>开始日期：2026-06-24 预计周期：3 周（冲刺） 每日时长：3 小时（每周约 5 天 → 周投入约 15 小时，3 周合计约 45 小时） 学习方式：<strong>概念吃透 → 当天动手 → 通过验收标准才算过</strong> 最终产出：一个完整的 AI 应用（前端 + 后端代理 + 流式 + 工具调用 + Agent），外加一套自己的 AI 编程工作流</p></blockquote><hr><h2 id="怎么用这份计划" tabindex="-1">怎么用这份计划 <a class="header-anchor" href="#怎么用这份计划" aria-label="Permalink to &quot;怎么用这份计划&quot;">​</a></h2><p>这是一门<strong>从零开始</strong>的课，不依赖任何已有基础。六个模块层层递进，每个模块都有三段：</p><ul><li><strong>🎯 学什么</strong> —— 这一阶段必须搞懂的概念</li><li><strong>💻 动手</strong> —— 当天就要敲的代码 / 实验</li><li><strong>✅ 验收标准</strong> —— 能做到这几条，才算真的会了，再往下走</li></ul><p><strong>铁律</strong>：不要只看不练。每个概念学完当天就写代码验证。看懂 ≠ 会，能从空白文件写出来才算会。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span>模块一 LLM 是什么 + 怎么调 API</span></span>
<span class="line"><span>   └─► 模块二 提示词工程（让输出可控）</span></span>
<span class="line"><span>          └─► 模块三 流式响应（前端体验核心）</span></span>
<span class="line"><span>                 └─► 模块四 Function Calling（让模型调用工具）</span></span>
<span class="line"><span>                        └─► 模块五 Agent（让模型自主编排）</span></span>
<span class="line"><span>                               └─► 模块六 AI 编程工具（用 AI 提效，贯穿全程）</span></span>
<span class="line"><span>                                      └─► 🏆 综合项目</span></span></code></pre></div><hr><h2 id="模块一-llm-与-api-调用-第-1-周-·-前半" tabindex="-1">模块一：LLM 与 API 调用（第 1 周 · 前半） <a class="header-anchor" href="#模块一-llm-与-api-调用-第-1-周-·-前半" aria-label="Permalink to &quot;模块一：LLM 与 API 调用（第 1 周 · 前半）&quot;">​</a></h2><h3 id="🎯-学什么" tabindex="-1">🎯 学什么 <a class="header-anchor" href="#🎯-学什么" aria-label="Permalink to &quot;🎯 学什么&quot;">​</a></h3><ul><li>大模型到底是什么：它本质是&quot;根据上文预测下一个 token&quot;，不是数据库、不是搜索引擎</li><li>三个必懂概念：<strong>Token</strong>（文本的计费/计量单位）、<strong>上下文窗口</strong>（一次能塞多少）、<strong>温度 temperature</strong>（随机性）</li><li>Chat 接口的核心结构：<code>messages</code> 数组 + 三种角色 <code>system</code> / <code>user</code> / <code>assistant</code></li><li>一次请求的生命周期：请求体 → 模型 → 响应体（含 <code>usage</code> 计费字段）</li><li><strong>前端铁律</strong>：API Key 绝对不能放在前端代码/浏览器里，必须经过自己的后端中转</li></ul><h3 id="💻-动手" tabindex="-1">💻 动手 <a class="header-anchor" href="#💻-动手" aria-label="Permalink to &quot;💻 动手&quot;">​</a></h3><ol><li>注册一个能用的模型服务（OpenAI / Claude / 通义千问 / DeepSeek 任选，国产的好上手）</li><li>用 <code>curl</code> 或 Node 的 <code>fetch</code> 直接发<strong>一次最原始的请求</strong>，不用任何 SDK，看清楚请求体和返回体长什么样</li><li>搭一个最小后端代理（Node + Express 或一个 Serverless 函数）：前端 → 你的 <code>/api/chat</code> → 模型，Key 只存在后端 <code>.env</code></li><li>前端写一个最简单的输入框 + 按钮 + 显示回答</li></ol><h3 id="✅-验收标准" tabindex="-1">✅ 验收标准 <a class="header-anchor" href="#✅-验收标准" aria-label="Permalink to &quot;✅ 验收标准&quot;">​</a></h3><ul><li>[ ] 能不看文档说清楚 system / user / assistant 各自的作用</li><li>[ ] 能手写一个不带任何 SDK 的 <code>fetch</code> 请求并调通</li><li>[ ] 你的前端代码里<strong>搜不到</strong> API Key</li><li>[ ] 能看懂返回里的 <code>usage</code>，知道这次花了多少 token</li></ul><hr><h2 id="模块二-提示词工程-第-1-周-·-后半" tabindex="-1">模块二：提示词工程（第 1 周 · 后半） <a class="header-anchor" href="#模块二-提示词工程-第-1-周-·-后半" aria-label="Permalink to &quot;模块二：提示词工程（第 1 周 · 后半）&quot;">​</a></h2><h3 id="🎯-学什么-1" tabindex="-1">🎯 学什么 <a class="header-anchor" href="#🎯-学什么-1" aria-label="Permalink to &quot;🎯 学什么&quot;">​</a></h3><ul><li>提示词的标准结构：<strong>角色 + 任务 + 约束 + 输出格式 + 示例</strong></li><li>核心技巧： <ul><li>Few-shot（给几个例子，模型照着学）</li><li>思维链 CoT（让它&quot;一步步想&quot;，复杂任务质量飙升）</li><li>分隔符（用 \`\`\` 或 XML 标签把&quot;用户数据&quot;和&quot;你的指令&quot;隔开）</li></ul></li><li><strong>结构化输出</strong>：让模型稳定返回 JSON，前端能直接 <code>JSON.parse</code> 消费（这是前端最实用的一招）</li><li>提示注入（Prompt Injection）是什么，怎么防</li></ul><h3 id="💻-动手-1" tabindex="-1">💻 动手 <a class="header-anchor" href="#💻-动手-1" aria-label="Permalink to &quot;💻 动手&quot;">​</a></h3><ol><li>选一个真实任务，比如&quot;把一段用户评论分类（正面/负面/中性）并提取关键词，返回 JSON&quot;</li><li>先写一版烂提示词，看它输出多不稳定</li><li>逐步加：角色设定 → 输出格式约束 → Few-shot 示例 → 要求纯 JSON</li><li>把它接到模块一的代理上，前端能展示解析后的结构化结果</li></ol><h3 id="✅-验收标准-1" tabindex="-1">✅ 验收标准 <a class="header-anchor" href="#✅-验收标准-1" aria-label="Permalink to &quot;✅ 验收标准&quot;">​</a></h3><ul><li>[ ] 同一个任务跑 10 次，输出格式稳定可被 <code>JSON.parse</code></li><li>[ ] 能说出 Few-shot 和 CoT 分别适合什么场景</li><li>[ ] 能写一个 System Prompt，让模型稳定扮演某个角色不跑偏</li><li>[ ] 知道如何用分隔符防止用户输入&quot;越权&quot;改变指令</li></ul><hr><h2 id="模块三-流式响应-第-2-周-·-前半-——-前端核心战场" tabindex="-1">模块三：流式响应（第 2 周 · 前半）—— 前端核心战场 <a class="header-anchor" href="#模块三-流式响应-第-2-周-·-前半-——-前端核心战场" aria-label="Permalink to &quot;模块三：流式响应（第 2 周 · 前半）—— 前端核心战场&quot;">​</a></h2><h3 id="🎯-学什么-2" tabindex="-1">🎯 学什么 <a class="header-anchor" href="#🎯-学什么-2" aria-label="Permalink to &quot;🎯 学什么&quot;">​</a></h3><ul><li>为什么要流式：不流式要等十几秒才出整段；流式像打字机，首字 0.5 秒就来</li><li>后端：请求加 <code>stream: true</code>，返回变成 <strong>SSE</strong>（<code>text/event-stream</code>），一行行 <code>data: {...}</code>，最后 <code>data: [DONE]</code></li><li>前端：用 <code>fetch</code> + <code>response.body.getReader()</code> + <code>TextDecoder</code> 逐块读取拼接 <ul><li>⚠️ 不要用老的 <code>EventSource</code>，它只支持 GET、不能带 body</li></ul></li><li>工程细节：用 <code>AbortController</code> 做&quot;停止生成&quot;、错误处理、Markdown 增量渲染</li></ul><h3 id="💻-动手-2" tabindex="-1">💻 动手 <a class="header-anchor" href="#💻-动手-2" aria-label="Permalink to &quot;💻 动手&quot;">​</a></h3><ol><li>把模块一的后端代理改成流式转发</li><li>前端用 <code>ReadableStream</code> 逐字渲染，做出打字机效果</li><li>加一个&quot;停止&quot;按钮（AbortController）</li><li>（进阶）了解 <a href="https://sdk.vercel.ai/" target="_blank" rel="noreferrer">Vercel AI SDK</a> 的 <code>useChat</code>，看它怎么把这套封装掉——理解原理后再用轮子</li></ol><h3 id="✅-验收标准-2" tabindex="-1">✅ 验收标准 <a class="header-anchor" href="#✅-验收标准-2" aria-label="Permalink to &quot;✅ 验收标准&quot;">​</a></h3><ul><li>[ ] 能不靠任何库，纯 <code>fetch</code> + <code>ReadableStream</code> 实现打字机效果</li><li>[ ] 能解释 SSE 数据格式，知道 <code>data: [DONE]</code> 的作用</li><li>[ ] &quot;停止生成&quot;按钮能真正中断请求</li><li>[ ] 能说清为什么前端流式不用 EventSource</li></ul><hr><h2 id="模块四-function-calling-第-2-周-·-后半-——-让模型动手" tabindex="-1">模块四：Function Calling（第 2 周 · 后半）—— 让模型动手 <a class="header-anchor" href="#模块四-function-calling-第-2-周-·-后半-——-让模型动手" aria-label="Permalink to &quot;模块四：Function Calling（第 2 周 · 后半）—— 让模型动手&quot;">​</a></h2><h3 id="🎯-学什么-3" tabindex="-1">🎯 学什么 <a class="header-anchor" href="#🎯-学什么-3" aria-label="Permalink to &quot;🎯 学什么&quot;">​</a></h3><ul><li>模型本身只会&quot;说话&quot;，Function Calling 让它能&quot;决定调用哪个函数、传什么参数&quot;</li><li>完整闭环： <ol><li>你用 <strong>JSON Schema</strong> 描述工具（name / description / parameters）</li><li>模型返回 <code>tool_calls</code>（它想调哪个工具、参数是什么）</li><li><strong>你的代码</strong>真正执行这个函数</li><li>把执行结果塞回 <code>messages</code>，再请求一次</li><li>模型基于结果给出最终回答</li></ol></li><li>关键认知：模型只负责&quot;决策调用&quot;，真正执行永远是你的代码</li></ul><h3 id="💻-动手-3" tabindex="-1">💻 动手 <a class="header-anchor" href="#💻-动手-3" aria-label="Permalink to &quot;💻 动手&quot;">​</a></h3><ol><li>定义 2-3 个工具：比如 <code>getWeather(city)</code>、<code>search(query)</code>、<code>calculate(expr)</code></li><li>写完整闭环：发请求 → 拿到 <code>tool_calls</code> → 本地执行 → 结果回注 → 再请求 → 拿最终答案</li><li>加错误兜底：工具执行失败时返回结构化错误，而不是崩</li></ol><h3 id="✅-验收标准-3" tabindex="-1">✅ 验收标准 <a class="header-anchor" href="#✅-验收标准-3" aria-label="Permalink to &quot;✅ 验收标准&quot;">​</a></h3><ul><li>[ ] 能从空白文件写出一个工具的 JSON Schema</li><li>[ ] 能完整跑通&quot;请求 → tool_calls → 执行 → 回注 → 最终答案&quot;</li><li>[ ] 问&quot;北京天气怎么样&quot;时，模型能正确选中 <code>getWeather</code> 并填对参数</li><li>[ ] 工具抛错时整个流程不崩，能优雅返回</li></ul><hr><h2 id="模块五-agent-开发-第-3-周-·-前半-——-让模型自主编排" tabindex="-1">模块五：Agent 开发（第 3 周 · 前半）—— 让模型自主编排 <a class="header-anchor" href="#模块五-agent-开发-第-3-周-·-前半-——-让模型自主编排" aria-label="Permalink to &quot;模块五：Agent 开发（第 3 周 · 前半）—— 让模型自主编排&quot;">​</a></h2><h3 id="🎯-学什么-4" tabindex="-1">🎯 学什么 <a class="header-anchor" href="#🎯-学什么-4" aria-label="Permalink to &quot;🎯 学什么&quot;">​</a></h3><ul><li>Agent = LLM 大脑 + 工具 + <strong>循环</strong> + 记忆。和单次调用的本质区别：它会自己多步决策直到完成任务</li><li><strong>ReAct 循环</strong>：Thought（想）→ Action（调工具）→ Observation（看结果）→ 再想……直到得出答案</li><li>工程要点：最大步数限制（防死循环）、每步日志追踪</li><li><strong>记忆</strong>：短期（对话历史 + token 窗口截断）、长期（对话结束提炼关键信息持久化）</li><li>把模块三的流式用上：把 Agent 的每一步实时推给前端可视化</li></ul><h3 id="💻-动手-4" tabindex="-1">💻 动手 <a class="header-anchor" href="#💻-动手-4" aria-label="Permalink to &quot;💻 动手&quot;">​</a></h3><ol><li>在模块四的工具基础上，写一个 <code>while</code> 主循环（ReAct，最大步数 6）</li><li>加记忆：对话历史管理 + 简单的长期记忆（存 JSON）</li><li>前端可视化 Agent 每一步：💭 思考 → 🔧 调用工具 → ✅ 观察结果 → 📝 最终回答</li></ol><h3 id="✅-验收标准-4" tabindex="-1">✅ 验收标准 <a class="header-anchor" href="#✅-验收标准-4" aria-label="Permalink to &quot;✅ 验收标准&quot;">​</a></h3><ul><li>[ ] 能讲清 Agent 和&quot;单次 LLM 调用&quot;的本质区别</li><li>[ ] 你的 Agent 能自己决定调用 2 个以上工具完成一个复合任务</li><li>[ ] 有最大步数限制，不会死循环</li><li>[ ] 前端能看到 Agent 每一步的执行过程</li></ul><hr><h2 id="模块六-ai-编程工具-codex-贯穿全程-第-3-周-·-后半专项" tabindex="-1">模块六：AI 编程工具 / Codex（贯穿全程 + 第 3 周 · 后半专项） <a class="header-anchor" href="#模块六-ai-编程工具-codex-贯穿全程-第-3-周-·-后半专项" aria-label="Permalink to &quot;模块六：AI 编程工具 / Codex（贯穿全程 + 第 3 周 · 后半专项）&quot;">​</a></h2><h3 id="🎯-学什么-5" tabindex="-1">🎯 学什么 <a class="header-anchor" href="#🎯-学什么-5" aria-label="Permalink to &quot;🎯 学什么&quot;">​</a></h3><ul><li>这类工具（Codex / Claude Code / Cursor）本质就是模块五学的那种 Agent，只不过工具是&quot;读写文件、跑命令&quot;</li><li><strong>不是让它替你写，是让它放大你</strong>：你定方向、做判断，它干重复劳动</li><li>高效用法（决定成败）： <ul><li>给足上下文（贴文件、贴报错、说清意图），而非&quot;帮我写个功能&quot;</li><li>让它<strong>先出计划再动手</strong>，你 review 通过再让它写</li><li>让它干：写测试、补类型、重构、写文档、解释陌生代码</li><li>用规则文件（如 <code>CLAUDE.md</code>）固化项目规范，让产出符合你的风格</li></ul></li><li><strong>质量底线</strong>：AI 写的代码必须你自己看懂再合并，让它解释为什么这么写</li></ul><h3 id="💻-动手-5" tabindex="-1">💻 动手 <a class="header-anchor" href="#💻-动手-5" aria-label="Permalink to &quot;💻 动手&quot;">​</a></h3><ul><li>从模块一开始，本计划的所有代码<strong>都用 AI 工具配合你写</strong>——边学边用就是最好的练习</li><li>Week 6 专项：用 AI 工具完成综合项目里你最不熟的部分，记录哪些提示有效、哪些翻车</li></ul><h3 id="✅-验收标准-5" tabindex="-1">✅ 验收标准 <a class="header-anchor" href="#✅-验收标准-5" aria-label="Permalink to &quot;✅ 验收标准&quot;">​</a></h3><ul><li>[ ] 日常开发已习惯用 AI 工具，能明显感到提速</li><li>[ ] 能写出让 AI 一次到位的高质量提示（带上下文、带约束）</li><li>[ ] 不会无脑合并——能识别并修正 AI 写错的地方</li><li>[ ] 写出一篇&quot;我的 AI 编程工作流&quot;笔记</li></ul><hr><h2 id="🏆-综合项目-第-3-周收尾" tabindex="-1">🏆 综合项目（第 3 周收尾） <a class="header-anchor" href="#🏆-综合项目-第-3-周收尾" aria-label="Permalink to &quot;🏆 综合项目（第 3 周收尾）&quot;">​</a></h2><p>把六个模块串成一个完整作品。推荐方向（选一个）：</p><table tabindex="0"><thead><tr><th>方向</th><th>用到的能力</th></tr></thead><tbody><tr><td>📚 <strong>知识库问答 Agent</strong>（推荐，用你这个 docs 仓库当语料）</td><td>全部六个模块</td></tr><tr><td>📝 智能周报助手</td><td>API + 提示词 + 工具调用</td></tr><tr><td>🔍 网页内容总结器（带流式）</td><td>API + 提示词 + 流式</td></tr><tr><td>🤖 多工具客服 Agent</td><td>全部六个模块</td></tr></tbody></table><p><strong>项目验收</strong>：前端界面 + 后端代理（Key 安全）+ 流式输出 + 至少 2 个工具的 Function Calling + Agent 多步编排 + 一份 README。</p><hr><h2 id="总进度追踪" tabindex="-1">总进度追踪 <a class="header-anchor" href="#总进度追踪" aria-label="Permalink to &quot;总进度追踪&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span>总进度：███░░░░░░░ ~25%   已完成 1.5 / 6 · 附赠 RAG 引擎 + 会话管理 + Redis 🚀</span></span></code></pre></div><blockquote><p>📍 <strong>下次从这里继续</strong>：模块三「流式响应」——打字机效果 + <code>AbortController</code> 停止生成。当天学完当天写 <code>demo/back/stream.ts</code>。</p></blockquote><table tabindex="0"><thead><tr><th>周</th><th>模块</th><th>状态</th><th>完成日期</th></tr></thead><tbody><tr><td>第 1 周 前半</td><td>一 · LLM 与 API 调用</td><td>✅ 已完成</td><td>2026-06-25</td></tr><tr><td>第 1 周 后半</td><td>二 · 提示词工程</td><td>✅ 已完成</td><td>2026-07-06</td></tr><tr><td>知识点扩展</td><td>RAG 引擎 + 会话管理 + Redis 存储</td><td>✅ 已完成</td><td>2026-07-06</td></tr><tr><td>第 2 周 前半</td><td>三 · 流式响应</td><td>⏳ 未开始</td><td>-</td></tr><tr><td>第 2 周 后半</td><td>四 · Function Calling</td><td>⏳ 未开始</td><td>-</td></tr><tr><td>第 3 周 前半</td><td>五 · Agent 开发</td><td>⏳ 未开始</td><td>-</td></tr><tr><td>第 3 周 后半</td><td>六 · AI 编程工具 + 综合项目</td><td>⏳ 未开始</td><td>-</td></tr></tbody></table><hr><h2 id="推荐资源" tabindex="-1">推荐资源 <a class="header-anchor" href="#推荐资源" aria-label="Permalink to &quot;推荐资源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>用途</th></tr></thead><tbody><tr><td><a href="https://platform.openai.com/docs/api-reference/chat" target="_blank" rel="noreferrer">OpenAI API 文档</a></td><td>Chat Completions 接口</td></tr><tr><td><a href="https://docs.anthropic.com/en/api/messages" target="_blank" rel="noreferrer">Anthropic API 文档</a></td><td>Claude Messages 接口</td></tr><tr><td><a href="https://www.promptingguide.ai/zh" target="_blank" rel="noreferrer">提示工程指南（中文）</a></td><td>提示词技巧</td></tr><tr><td><a href="https://platform.openai.com/docs/guides/function-calling" target="_blank" rel="noreferrer">OpenAI Function Calling</a></td><td>工具调用规范</td></tr><tr><td><a href="https://sdk.vercel.ai/" target="_blank" rel="noreferrer">Vercel AI SDK</a></td><td>前端流式集成</td></tr><tr><td><a href="https://docs.claude.com/en/docs/claude-code/overview" target="_blank" rel="noreferrer">Claude Code 文档</a></td><td>AI 编程工具</td></tr><tr><td><a href="https://docs.cursor.com/" target="_blank" rel="noreferrer">Cursor 文档</a></td><td>IDE 内 AI 编程</td></tr></tbody></table>`,69)])])}const g=e(r,[["render",i]]);export{p as __pageData,g as default};
